<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Tenant extends Model{protected $guarded=[]; public function users(){return $this->belongsToMany(User::class);} public function channels(){return $this->belongsToMany(Channel::class,'tenant_channel');} public function topics(){return $this->hasMany(Topic::class);} public function campaigns(){return $this->hasMany(Campaign::class);} public function contentAssets(){return $this->hasMany(ContentAsset::class);} public function competitors(){return $this->hasMany(Competitor::class);} public function benchmarkCompanies(){return $this->hasMany(BenchmarkCompany::class);} }
